SELECT EXISTS(SELECT 1 FROM (SELECT m.*,m.host_id AS owner FROM owned_meets m)t WHERE t.id=$2 AND t.deleted_at IS NULL AND t.status=0 AND t.expires_at>clock_timestamp() AND EXISTS(SELECT 1 FROM owned_authority_accounts a WHERE a.id=t.owner AND NOT a.disabled AND NOT EXISTS(SELECT 1 FROM owned_authority_punishments u WHERE u.account_id=a.id AND u.kind='disable_account' AND(u.starts_at IS NULL OR u.starts_at<=clock_timestamp())AND(u.expires_at IS NULL OR u.expires_at>clock_timestamp()))) AND NOT EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.status=-100 AND((b.account_id=t.owner AND b.related_id=NULLIF($1::text,'')::uuid)OR(b.related_id=t.owner AND b.account_id=NULLIF($1::text,'')::uuid))) AND(t.owner=NULLIF($1::text,'')::uuid OR EXISTS(SELECT 1 FROM owned_meet_participants mp WHERE mp.meet_id=t.id AND mp.account_id=NULLIF($1::text,'')::uuid)OR(t.visibility<>1 AND((EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.account_id=t.owner AND b.related_id=NULLIF($1::text,'')::uuid AND b.status>=100)AND EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.related_id=t.owner AND b.account_id=NULLIF($1::text,'')::uuid AND b.status>=100)) OR EXISTS(SELECT 1 FROM owned_meet_participants mp JOIN owned_authority_accounts a ON a.id=mp.account_id WHERE mp.meet_id=t.id AND NOT a.disabled AND NOT EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.status=-100 AND((b.account_id=mp.account_id AND b.related_id=NULLIF($1::text,'')::uuid)OR(b.related_id=mp.account_id AND b.account_id=NULLIF($1::text,'')::uuid)))AND EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.account_id=mp.account_id AND b.related_id=NULLIF($1::text,'')::uuid AND b.status>=100)AND EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.related_id=mp.account_id AND b.account_id=NULLIF($1::text,'')::uuid AND b.status>=100))))))
